// 站点图标(favicon.ico)的唯一来源 —— 与 fastapi/app/favicon.ico 是同一个文件(48725 字节)
// 内联成 base64 而不从 R2 取(每个页面、未登录都要能拿到); 生成方式: node tools/embed_favicon.mjs
const FAVICON_BASE64 = '';

//: 与旧站 StaticFiles 的 MIME 一致(实测线上 /favicon.ico 返回 image/x-icon)
export const FAVICON_CONTENT_TYPE = 'image/x-icon';

//: 内容指纹做 ETag: 图标不变则标签不变, 浏览器可走 304
export const FAVICON_ETAG = '"31ebbc0efe0389e2"';

let cached = null;

/** 图标原始字节(首次调用解码, 之后复用)。 */
export function faviconBytes() {
  if (cached) return cached;
  const binary = atob(FAVICON_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
  cached = bytes;
  return cached;
}

/** /favicon.ico 的响应: 根绝对路径(自定义域与预览域都成立), 必须由 Worker 自己响应, 见 DEPLOY.md。 */
export function faviconResponse() {
  const bytes = faviconBytes();
  return new Response(bytes, {
    headers: {
      'content-type': FAVICON_CONTENT_TYPE,
      'content-length': String(bytes.length),
      'cache-control': 'public, max-age=604800',
      etag: FAVICON_ETAG
    }
  });
}
